def medmcqa_solution_format_strict(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        m = re.search(r'<solution>\s*([A-Da-d])\s*</solution>', text)
        if m:
            out.append(2.0)
        else:
            out.append(-2.0)
    return out

def medmcqa_group_consistency(prompts, completions, answer, **kwargs):
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    out = [0.0] * len(completions)
    for idx in groups.values():
        preds = {i: extract_solution(completions[i][0]['content']) for i in idx}
        valid_preds = [p for p in preds.values() if p]
        if not valid_preds:
            continue

        # Count frequencies
        freq = {}
        for p in valid_preds:
            freq[p] = freq.get(p, 0) + 1

        max_count = max(freq.values())
        majority_answer = [k for k, v in freq.items() if v == max_count][0]

        for i in idx:
            if preds[i] == majority_answer:
                out[i] = 1.0
            else:
                out[i] = -0.5
    return out

def medmcqa_answer_position(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', text, re.DOTALL)
        if not m:
            out.append(-1.0)
            continue

        pred = m.group(1).strip()
        if is_correct(pred, gt):
            # Reward if the answer is concise in the solution tag
            if len(pred) <= 2:
                out.append(2.0)
            else:
                out.append(1.0)
        else:
            out.append(-1.0)
    return out

def medmcqa_length_relative(prompts, completions, answer, **kwargs):
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    out = [0.0] * len(completions)
    for idx in groups.values():
        lens = [len(completions[i][0]['content']) for i in idx]
        mu = sum(lens) / len(lens)
        sd = (sum((x - mu) ** 2 for x in lens) / len(lens)) ** 0.5 if len(lens) > 1 else 1.0

        for i in idx:
            z = (lens[i] - mu) / (sd + 1e-6)
            # Penalize outliers in length
            out[i] = -0.5 * abs(z)
    return out

